mapper.select:


    del_flag = '0'
     AND qc_no LIKE CONCAT('%', #{qcNo}, '%')
     AND work_order_no LIKE CONCAT('%', #{workOrderNo}, '%')
     AND process_name LIKE CONCAT('%', #{processName}, '%')
     AND qc_type = #{qcType}
     AND (qc_result IS NULL OR qc_result = '')
     AND qc_result = #{qcResult}
     AND qc_by LIKE CONCAT('%', #{qcBy}, '%')
     AND date(create_time) >= #{params.beginTime}
     AND date(create_time) <= #{params.endTime}

ORDER BY qc_id DESC
